<?php
require __DIR__ . '/app/bootstrap.php';
$userId=require_auth();$pdo=db();
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='checkin') {verify_csrf();try{$r=(new CheckinService($pdo))->checkIn($userId,(string)($_POST['response']??'yes'));flash('success',$r['message']);}catch(Throwable $e){flash('error','The check-in did not save.');}redirect('today.php');}
$user=current_user();$profile=(new VacationProfileService($pdo))->snapshot($userId);$summary=$profile['summary'];$score=$profile['score'];$streak=(int)($summary['current_streak']??0);
$stmt=$pdo->prepare('SELECT a.id,a.name,a.description,ua.unlocked_at FROM user_achievements ua JOIN achievements a ON a.id=ua.achievement_id WHERE ua.user_id=? AND ua.completed=1 ORDER BY ua.unlocked_at DESC LIMIT 3');$stmt->execute([$userId]);$achievements=$stmt->fetchAll();
$stmt=$pdo->prepare('SELECT id FROM daily_checkins WHERE user_id=? AND checkin_date=?');$stmt->execute([$userId,date('Y-m-d')]);$checkedToday=(bool)$stmt->fetch();
$seedComment=(new FunContentService($pdo))->random('agent_comment',$userId);$agentLine=$seedComment?(string)$seedComment['body']:($checkedToday?'Today is counted. The condition remains aggressively vacation-related.':'Have you thought about vacation today, or do I need to open a beach tab for you?');
$dreams=(new DreamService($pdo))->all($userId);$latestDream=$dreams[0]??null;$success=flash('success');$error=flash('error');$title='Today — Vacation Brain';require __DIR__.'/partials/header.php';
?>
<section class="dashboard today-v2"><div class="shell">
